using UnityEditor;using UnityEngine;using UnityEngine.AI;using Codice.Bosses;
public static class AgentChunkSize{public static string Run(){const float target=13;string path="Assets/Resources/ExpeditionEnemies/Big Chunk.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var c=root.GetComponent<CapsuleCollider>();float k=target/c.height;if(Mathf.Abs(k-1)<.02f)return "already "+c.height;var b=root.GetComponent<BossCharacter>();b.visual.localScale*=k;b.visual.localPosition*=k;c.height=target;c.radius*=k;c.center=Vector3.up*target*.5f;var a=root.GetComponent<NavMeshAgent>();a.height=target;a.radius=Mathf.Min(c.radius,3.2f);a.baseOffset=0;PrefabUtility.SaveAsPrefabAsset(root,path);return $"Big Chunk x{k:F2}: height {target} m, capsule radius {c.radius:F2}, agent radius {a.radius:F2}";}finally{PrefabUtility.UnloadPrefabContents(root);}}}
